import java.nio.charset.*;import java.nio.file.*;import java.sql.*;import java.util.regex.*;
public class FindMissingXwgIds{public static void main(String[]a)throws Exception{String y=Files.readString(Path.of("src/main/resources/application.yml"),StandardCharsets.UTF_8);try(Connection c=DriverManager.getConnection(v(y,"url").replace("192.168.3.5","127.0.0.1"),v(y,"username"),v(y,"password"));var s=c.createStatement();var r=s.executeQuery("SELECT x.source_id,x.school_name FROM xueweigui_school_source x LEFT JOIN school s ON s.xueweigui_school_id=x.source_id WHERE s.id IS NULL ORDER BY x.source_id")){while(r.next())System.out.println(r.getInt(1)+"\t"+r.getString(2));}}static String v(String y,String k){var m=Pattern.compile("(?m)^\\s*"+k+":\\s*([^\\r\\n#]+)").matcher(y);m.find();String z=m.group(1).trim();var p=Pattern.compile("\\$\\{([^:}]+)(?::([^}]*))?}").matcher(z);if(!p.matches())return z;String e=System.getenv(p.group(1));return e!=null&&!e.isBlank()?e:p.group(2);}}
